CREATE TABLE IF NOT EXISTS businesses (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) NOT NULL, profile JSON NOT NULL, demo_mode BOOLEAN NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('owner','manager') NOT NULL DEFAULT 'manager', permissions JSON NOT NULL, active BOOLEAN NOT NULL DEFAULT 1, is_demo BOOLEAN NOT NULL DEFAULT 0, last_login DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_attempts (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, fingerprint CHAR(64) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(fingerprint,created_at)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, company VARCHAR(160) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', phone VARCHAR(40) NOT NULL DEFAULT '', address TEXT NOT NULL, gstin VARCHAR(20) NOT NULL DEFAULT '', notes TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Active', is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(business_id,name), FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, description TEXT NOT NULL, sku VARCHAR(60) NOT NULL DEFAULT '', category VARCHAR(80) NOT NULL DEFAULT 'Service', unit VARCHAR(30) NOT NULL DEFAULT 'unit', price DECIMAL(14,2) NOT NULL, tax_rate DECIMAL(5,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'Active', is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS leads (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, company VARCHAR(160) NOT NULL DEFAULT '', email VARCHAR(190) NOT NULL DEFAULT '', phone VARCHAR(40) NOT NULL DEFAULT '', value DECIMAL(14,2) NOT NULL DEFAULT 0, stage VARCHAR(40) NOT NULL DEFAULT 'New', source VARCHAR(80) NOT NULL DEFAULT 'Website', close_date DATE NULL, follow_up DATE NULL, assigned_to BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NULL, notes TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Active', is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(assigned_to) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tasks (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, title VARCHAR(200) NOT NULL, description TEXT NOT NULL, due_date DATE NOT NULL, priority VARCHAR(30) NOT NULL DEFAULT 'Medium', status VARCHAR(30) NOT NULL DEFAULT 'Pending', assigned_to BIGINT UNSIGNED NULL, customer_id BIGINT UNSIGNED NULL, completed_at DATETIME NULL, is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(assigned_to) REFERENCES users(id), FOREIGN KEY(customer_id) REFERENCES customers(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documents (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, type ENUM('invoice','quotation') NOT NULL, number VARCHAR(50) NOT NULL, issue_date DATE NOT NULL, due_date DATE NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Draft', subtotal DECIMAL(14,2) NOT NULL, discount_total DECIMAL(14,2) NOT NULL DEFAULT 0, tax_total DECIMAL(14,2) NOT NULL DEFAULT 0, total DECIMAL(14,2) NOT NULL, snapshot JSON NULL, notes TEXT NOT NULL, source_id BIGINT UNSIGNED NULL, is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(business_id,number), UNIQUE(business_id,source_id), INDEX(business_id,type,issue_date), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(customer_id) REFERENCES customers(id), FOREIGN KEY(source_id) REFERENCES documents(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS document_items (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, document_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NULL, description VARCHAR(500) NOT NULL, quantity DECIMAL(12,3) NOT NULL, rate DECIMAL(14,2) NOT NULL, discount_rate DECIMAL(5,2) NOT NULL DEFAULT 0, tax_rate DECIMAL(5,2) NOT NULL, subtotal DECIMAL(14,2) NOT NULL, discount_total DECIMAL(14,2) NOT NULL, tax_total DECIMAL(14,2) NOT NULL, total DECIMAL(14,2) NOT NULL, FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(product_id) REFERENCES products(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payments (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, document_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NOT NULL, payment_date DATE NOT NULL, amount DECIMAL(14,2) NOT NULL, method VARCHAR(40) NOT NULL, reference VARCHAR(160) NOT NULL DEFAULT '', notes TEXT NOT NULL, idempotency_key CHAR(64) NOT NULL, reversed_at DATETIME NULL, reversal_reason VARCHAR(300) NULL, is_demo BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(business_id,idempotency_key), INDEX(business_id,payment_date), FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(document_id) REFERENCES documents(id), FOREIGN KEY(customer_id) REFERENCES customers(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS expenses (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, description VARCHAR(200) NOT NULL, category VARCHAR(80) NOT NULL, amount DECIMAL(14,2) NOT NULL, expense_date DATE NOT NULL, method VARCHAR(40) NOT NULL DEFAULT 'Bank transfer', vendor VARCHAR(160) NOT NULL DEFAULT '', reference VARCHAR(160) NOT NULL DEFAULT '', notes TEXT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Active', is_demo BOOLEAN NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS business_settings (
 business_id BIGINT UNSIGNED NOT NULL, setting_key VARCHAR(80) NOT NULL, value JSON NOT NULL, PRIMARY KEY(business_id,setting_key), FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS user_preferences (
 user_id BIGINT UNSIGNED PRIMARY KEY, value JSON NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS activity_logs (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity VARCHAR(60) NOT NULL, entity_id BIGINT UNSIGNED NULL, details JSON NOT NULL, is_demo BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(business_id,created_at), FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS backup_records (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, filename VARCHAR(100) NOT NULL, checksum CHAR(64) NOT NULL, bytes BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_provider_configs (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, name VARCHAR(120) NOT NULL, protocol VARCHAR(40) NOT NULL, endpoint VARCHAR(500) NOT NULL, model VARCHAR(160) NOT NULL, encrypted_key TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_conversations (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_messages (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, conversation_id BIGINT UNSIGNED NOT NULL, role VARCHAR(20) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_action_proposals (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, action VARCHAR(80) NOT NULL, payload JSON NOT NULL, token_hash CHAR(64) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'Pending', expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_memory_entries (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS ai_prompt_versions (
 id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, business_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(business_id) REFERENCES businesses(id), FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(50) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
